def abs_page(aid):
    url=f"https://arxiv.org/abs/{aid}"
    st, h = get(url)
    def grab(pat):
        m=re.search(pat,h,re.S)
        return re.sub(r"\s+"," ",html.unescape(re.sub(r"<[^>]+>"," ",m.group(1)))).strip() if m else ""
    title = grab(r'<h1 class="title[^"]*">(.*?)</h1>').replace("Title:","").strip()
    abst  = grab(r'<blockquote class="abstract[^"]*">(.*?)</blockquote>').replace("Abstract:","").strip()
    subj  = grab(r'<td class="tablecell subjects">(.*?)</td>')
    jref  = grab(r'<td class="tablecell jref">(.*?)</td>')
    comm  = grab(r'<td class="tablecell comments[^"]*">(.*?)</td>')
    dat   = grab(r'<div class="dateline">(.*?)</div>')
    return {"url":url,"status":st,"title":title,"abstract":abst,"jref":jref,"comments":comm,"dateline":dat}

